questionvariables.text:
/* --- Angaben fuer die Aufgabenstellung (weiterhin randomisiert, bewusst UNABHAENGIG von der
   festen Skizzen-Geometrie unten: fuer das Freischnittueben ist nicht wesentlich, dass die
   angegebenen Zahlenwerte exakt zur Skizze passen) --- */
r: 2;
h: rand_with_step(0.5, 1.5, 0.25);
alphaDeg: float(acos((r-h)/r)*180/%pi);
ta1: sconcat("h=",h,"; r=",r,"; alpha=",dispsf(alphaDeg,4),"°");

/* sin(alpha)/cos(alpha) als Referenz fuer die vorgeschaltete numerische Abfrage (PRT "alpha")
   sowie fuer die Anzeige des Inputs selbst - alpha ist hier die Zahl alphaDeg, nicht zu
   verwechseln mit dem GLEICHNAMIGEN freien Symbol "alpha", das weiter unten in den
   Gleichgewichtsbedingungen rein symbolisch verwendet wird. */
sinalpha_ref: float(sin(alphaDeg*%pi/180));
cosalpha_ref: float(cos(alphaDeg*%pi/180));

/* --- Skizzen-Geometrie: FEST, nicht randomisiert. rS (Rollenradius fuer die Anzeige) und hS
   (Stufenhoehe, eine Gittereinheit) sind die einzigen frei gewaehlten Werte; alles andere wird
   daraus berechnet, insbesondere xOS aus der Tangentialbedingung
   xOS^2 + (rS-hS)^2 = rS^2 (Walze tangiert sowohl Boden als auch Stufenkante B). Fuer rS=2.5,
   hS=1 ergibt das zufaellig xOS=-2 (exakt auf dem 0.1-Gitter), sodass die Gewichtskraft G beim
   Ziehen per gewoehnlichem Gitter-Snap praezise angetragen werden kann; bei anderer Wahl von rS
   waere das nicht mehr garantiert. --- */
rS: 2.5;
hS: 1;
xOS: -sqrt(hS*(2*rS-hS));
alphaS: float(acos((rS-hS)/rS)*180/%pi);
phiDeg: 20; /* rein illustrativer Neigungswinkel der Kraft in der Skizze */
Flen: rS+1.5;
Ftip: float([xOS+Flen*cos(phiDeg*%pi/180), rS+Flen*sin(phiDeg*%pi/180)]);
xO_center: [xOS, rS];

/* Blickfeld: knapp 1 Gittereinheit Rand um den tatsaechlichen Bildinhalt; pix immer 40 */
xmin: floor(min(xOS-rS,xOS)-1);
xmax: ceiling(max(Ftip[1],0)+1);
ymin: -2;
ymax: ceiling(max(Ftip[2],2*rS)+1);
pix: 40;

/* Richtung der Reaktion bei B: radial von der Stufenkante B zum Walzenmittelpunkt O */
dO: float(-[xOS, rS-hS]);
dOu: dO/sqrt(dO[1]^2+dO[2]^2);

/* Position des forceGen-Widgets: im unteren Rand, rechts, immer frei von der Skizze */
fgx: xmax-1.5;
fgy: ymax-0.9;

/* --- interaktive Ausgangsskizze --- */
initdata: [
  ["grid", "","", xmin,xmax,ymin,ymax, pix, [1,1], [0,0]],
  ["wall","Boden",[0,0],[xmin,0], 45, "show"],
  ["wall","Stufe links",[0,0],[0,hS], -45, "show"],
  ["wall","Stufe oben",[xmax,hS],[0,hS], 45, "show"],
  ["circle","r",xO_center, rS, -135],
  ["point","A",[xOS,0]],
  ["point","B",[0,hS]],
  ["line","black",[xOS-(rS+0.2),xOS+(rS+0.2)],[rS,rS],"-."],
  ["line","black",[xOS,xOS],[-0.2,2*rS+0.2],"-."],
  ["angle","\\alpha",[xOS,rS],[xOS,0],0.5,alphaS],
  ["angle","\\varphi",[xOS,rS],[xOS+1,rS],0.9,phiDeg],
  ["dim","h",[2,0],[2,hS],0],
  ["force","F",[xOS,rS],Ftip,10,""],
  ["contact","",[xOS,0],[0,-1],"Boden", 3],
  ["contact","",[0,hS],dO,["Stufe links","Stufe oben"],3],
  ["forceGen","F",[fgx,fgy]]
];
init: stackjson_stringify(initdata);

i_contactA: 14;
i_contactB: 15;


/* --- refdata/gfbdata werden aus initdata ABGELEITET (Objekte angehaengt/veraendert), damit
   Anpassungen an der Geometrie nur an EINER Stelle (initdata) gemacht werden muessen --- */
refdata: copylist(initdata);
refdata: endcons( ["force","G", xO_center, [xOS,rS-1.5], 10, "active"], refdata);
refdata: endcons( ["force","N_A", float([xOS,0]-[0,1.5]), [xOS,0], 10, "active"] , refdata);
refdata: endcons( ["force","N_B", float([0,hS]-dOu*1.5), [0,hS], 10, "active"] , refdata);
refdata[2][6]: "hide";
refdata[3][6]: "hide";
refdata[4][6]: "hide";
ref: stackjson_stringify(refdata);

gfbdata: copylist(refdata);
gfb: stackjson_stringify(gfbdata);

stack_include("https://raw.githubusercontent.com/mkraska/meclib/dev2026/Maxima/fb_value.mac" );
stack_include("https://raw.githubusercontent.com/mkraska/meclib/dev2026/Maxima/fb_fbd.mac" );

feedbackvariables.text:
obj: stackjson_parse(objects);
[textA, okA]: fb_contact(obj, names, i_contactA, "Kontakt A: ");
[textB, okB]: fb_contact(obj, names, i_contactB, "Kontakt B: ");
[textG, okG]: fb_force(obj, "G", xO_center, -90, 2, 0.01, "Gewichtskraft: ");
S_numforce: length(sublist_indices (obj, lambda ([x], x[1]="force")));
numforce: length(sublist_indices (refdata, lambda ([x], x[1]="force")));

obj: stackjson_parse(objects);
nameA: fb_reaction_name(obj, names, i_contactA, false);
nameB: fb_reaction_name(obj, names, i_contactB, false);
if nameA = false or nameB = false then (
  textGGx: "Vervollständigen Sie zuerst den Freischnitt (Reaktionen bei A und B).",
  okGGx: false
) else (
  GGx_ref: F*cos(phi) - nameB*sin(alpha),
  textGGx: fb_vars(S_GGx, GGx_ref, [F, nameB]),
  okGGx: is(textGGx = "")
);

obj: stackjson_parse(objects);
nameA: fb_reaction_name(obj, names, i_contactA, false);
nameB: fb_reaction_name(obj, names, i_contactB, false);
if nameA = false or nameB = false then (
  textGGy: "Vervollständigen Sie zuerst den Freischnitt (Reaktionen bei A und B).",
  okGGy: false
) else (
  GGy_ref: F*sin(phi) + nameA + nameB*cos(alpha) - G,
  textGGy: fb_vars(S_GGy, GGy_ref, [F, nameA, nameB, G]),
  okGGy: is(textGGy = "")
);
